// Central configuration for every platform / external endpoint the widget calls.
// Nothing here is tenant-specific: tenant URLs are resolved at runtime through
// i3DXCompassServices (see utils/initApp.js). Values that differ per deployment are
// read from build-time environment variables (see README "Configuration").
//
// Verification status (see docs/PLATFORM_INTEGRATION.md):
//   VERIFIED-IN-TENANT – already used successfully by this widget before this change.
//   TO-CONFIRM        – documented 3DEXPERIENCE "Document Web Services" call; the exact
//                        path/payload must be confirmed against DSDoc for your release.

const env = (name, fallback = "") => (process.env[name] ?? fallback).toString().trim();

export const PLATFORM = {
  // VERIFIED-IN-TENANT
  personContext:
    "/resources/modeler/pno/person?current=true&select=preferredcredentials&select=collabspaces",
  federatedSearch: "/federated/search",

  // CSRF token for 3DSpace write calls. TO-CONFIRM: header name.
  csrf: {
    url: "/resources/v1/application/CSRF",
    header: env("VUE_APP_CSRF_HEADER", "ENO_CSRF_TOKEN"),
  },

  // 3DSpace Document Web Services. GET {base}/{id} is VERIFIED-IN-TENANT (detailApi.js);
  // the other calls are TO-CONFIRM.
  documents: {
    base: "/resources/v1/modeler/documents",
    checkinTicket: "/resources/v1/modeler/documents/files/CheckinTicket", // PUT
    downloadTicket: (docId, fileId) =>
      `/resources/v1/modeler/documents/${encodeURIComponent(docId)}/files/${encodeURIComponent(fileId)}/DownloadTicket`, // PUT
  },
};

// How dashboard definitions are stored as Document objects.
export const DASHBOARD_DOC = {
  // Document type created and searched for. Set VUE_APP_DASHBOARD_DOC_TYPE when the
  // administrator provides a dedicated sub-type (recommended).
  type: env("VUE_APP_DASHBOARD_DOC_TYPE", "Document"),
  // Optional lifecycle policy for the created document (empty = platform default).
  policy: env("VUE_APP_DASHBOARD_DOC_POLICY", ""),
  // Marker written at the start of the document description so that dashboard
  // documents can be told apart from ordinary documents in search results.
  // Set VUE_APP_DASHBOARD_DOC_MARKER="" when a dedicated sub-type is used.
  marker: env("VUE_APP_DASHBOARD_DOC_MARKER", "DWDASHBOARD"),
  // Name of the JSON file checked in to the document.
  fileName: "dashboard.dwdash.json",
  // Page size and maximum number of dashboards listed.
  pageSize: 100,
  maxResults: 1000,
};

// Native per-user sharing (FR-11..FR-14) through the 3DSpace ownership services used
// by the platform "Share" command. VERIFIED-IN-TENANT from the native Share panel:
//   POST {ownership}        { businessObject:[{objectID}] }      -> who has access
//   POST {update}           { ownershipVector:[...] }            -> ADD (grant / change level) | REMOVE
//   POST {logicalAccess}    { businessObject:[{objectID}] }      -> access levels allowed on the object
//   POST {checkAccess}      { boAccessRights:[...changesov] }    -> may the current user share it
// Every call carries ?tenant=<platformId> and the SecurityContext header.
export const SHARING = {
  enabled: env("VUE_APP_SHARING_ENABLED", "true") !== "false",
  ownership: "/resources/pno/ownership",
  update: "/resources/pno/ownership/update",
  logicalAccess: "/resources/pno/ownership/logicalaccess",
  checkAccess: "/resources/pno/ownership/checkaccess",
  shareRight: "changesov",
  // A person is addressed by "<username><suffix>" (e.g. DemoUser2 -> DemoUser2_PRJ),
  // as observed in the native Share calls.
  personIdSuffix: env("VUE_APP_SHARE_PERSON_ID_SUFFIX", "_PRJ"),
  // Display order and fallback labels. The levels actually offered come from
  // logicalAccess for each document.
  levels: [
    { value: "Viewer", label: "Can View" },
    { value: "Reader", label: "Can Read" },
    { value: "ReaderR", label: "Can Read (Restricted)" },
    { value: "Author", label: "Can Edit" },
    { value: "Owner", label: "Can Manage" },
  ],
  defaultLevel: "Viewer",
  // The one access level the Share dialog gives. People it is shared with can open the
  // dashboard and save their own copy; only the owner can change or share it.
  // "Reader" (Can Read) also lets them download the dashboard file, which opening needs.
  shareLevel: env("VUE_APP_SHARE_LEVEL", "Reader"),
  // Value the platform uses for "no access" (REMOVE operation / removed entries).
  noAccess: "Empty",
};

// Project Schedule shows only projects assigned to the current user (FR-16/FR-20),
// in both "Single project" and "All projects".
// A project is assigned to the user when:
//   - the user is a member: the user's own Person object in the search index lists the
//     project under ds6w:where/ds6w:context/ds6w:usedInProject (observed on Person
//     results in the tenant), and the project is a Project Space the user can see; or
//   - the user owns it: the Project Space's PROJECT_SCOPE.predicate (ds6w:responsible)
//     matches the user. Set VUE_APP_PROJECT_SCOPE_INCLUDE_OWNED=false to drop this part.
// Request throttling. The federated search service answers "429 Too Many Requests" when
// a user sends many searches at once (e.g. Project Schedule > All projects), so searches
// are queued with at most `searchConcurrency` in flight, and a 429/503 on a read call is
// retried after the server's Retry-After time (or an increasing delay).
export const THROTTLE = {
  searchConcurrency: Math.max(1, parseInt(env("VUE_APP_SEARCH_CONCURRENCY", "3"), 10) || 3),
  maxRetries: 6,
  baseDelayMs: 2000,
  maxDelayMs: 30000,
  // after a 429/503, every search waits this long (or the server's Retry-After) before the
  // next one is sent, so queued searches don't keep hitting the limit
  cooldownMs: 3000,
};

export const PROJECT_SCOPE = {
  memberPredicate: "ds6w:where/ds6w:context/ds6w:usedInProject",
  includeOwned: env("VUE_APP_PROJECT_SCOPE_INCLUDE_OWNED", "true") !== "false",
  predicate: env("VUE_APP_PROJECT_SCOPE_PREDICATE", "ds6w:responsible"),
  label: env("VUE_APP_PROJECT_SCOPE_LABEL", "projects assigned to you"),
  concurrency: 2, // projects read at once when a project is read on its own
  nameChunk: 20, // project names checked per Project Space search
  taskChunk: 10, // projects whose tasks are read with one search per work type
  taskPageSize: 100, // results per page for those searches
};

// Optional external services (project-specific; empty = feature unavailable).
export const EXTERNAL = {
  typeConfigUrl: env("VUE_APP_TYPE_CONFIG_URL"),
  externalApiBase: env("VUE_APP_EXT_BASE"),
};

// Tenant time zone used to turn calendar dates into search ranges.
// Default: the browser's own zone. Override with VUE_APP_TIMEZONE (IANA name).
export const TIMEZONE = env("VUE_APP_TIMEZONE") || Intl.DateTimeFormat().resolvedOptions().timeZone;
