// Reading values from federated-search results, which look like
// { attributes: [{ name: "ds6w:label", value: "…" | ["…", "…"] }] }.
// Shared by the services so every one of them reads results the same way.

// Wraps a single value in an array; null/undefined become [].
export const toArray = (value) => [].concat(value ?? []);

// Every value of one attribute, as an array ([] when the attribute is missing).
export function allValues(result, name) {
  return toArray((result.attributes || []).find((a) => a.name === name)?.value);
}

// The first value of one attribute, as returned by the search ("" when missing).
export function firstValue(result, name) {
  return allValues(result, name)[0] ?? "";
}

// The first value of one attribute, converted to a string.
export function firstText(result, name) {
  return String(firstValue(result, name));
}

// The first non-empty value among several attribute names, as a string.
export function firstTextOf(result, names) {
  return names.map((n) => firstText(result, n)).find(Boolean) || "";
}

// Escapes a value placed inside double quotes in a search query: [field]:"<value>".
export function escapeQueryValue(value) {
  return String(value).replace(/\\/g, "\\\\").replace(/"/g, '\\"');
}
