// Picks the security contexts in which a new dashboard Document can be created, so the
// user is not asked to choose a collaborative space. Pure functions, no platform calls.
//
// A context is "ctx::<Role>.<Organization>.<Collaborative space>". Whether a role may
// create a Document is decided by 3DSpace; the ranking below only sets the order in
// which contexts are tried. Unknown (custom) roles are tried after the standard
// create-capable roles; Reader is never tried because it cannot create objects.

const ROLE_RANK = {
  VPLMProjectAdministrator: 5, // Owner
  VPLMProjectLeader: 4, // Leader
  VPLMCreator: 3, // Author
  VPLMContributor: 1, // Contributor
  VPLMViewer: 0, // Reader
};
const UNKNOWN_RANK = 2;

export function roleOf(ctx) {
  return String(ctx || "").replace(/^ctx::/, "").split(".")[0] || "";
}

function rankOf(ctx) {
  const role = roleOf(ctx);
  return role in ROLE_RANK ? ROLE_RANK[role] : UNKNOWN_RANK;
}

// options: [{ value: "ctx::Role.Org.Space" }] (store.ctxOptions) or plain strings.
// preferred: contexts to try first among those with the same rank (e.g. the context that
// worked last time, then the widget's Credentials preference).
// Returns context strings, best first, without duplicates and without Reader contexts.
export function orderSaveContexts(options = [], preferred = []) {
  const all = options.map((o) => (typeof o === "string" ? o : o?.value)).filter(Boolean);
  // When the user's context list is known, a preferred context outside it is stale and skipped.
  if (!all.length) all.push(...preferred.filter(Boolean));
  const unique = [...new Set(all)].filter((c) => rankOf(c) > 0);
  const pos = (c) => {
    const i = preferred.indexOf(c);
    return i === -1 ? preferred.length : i;
  };
  // A context that already worked is tried first, whatever its rank.
  const known = preferred[0] && unique.includes(preferred[0]) ? preferred[0] : "";
  return unique
    .map((c, i) => ({ c, i }))
    .sort((a, b) => {
      if (a.c === known) return -1;
      if (b.c === known) return 1;
      return rankOf(b.c) - rankOf(a.c) || pos(a.c) - pos(b.c) || a.i - b.i;
    })
    .map((x) => x.c);
}

// True when 3DSpace refused to create the object because of the role in the security
// context (error 1500028, "No create access …"). Any other error is not retried.
export function isNoCreateAccess(err) {
  if (!err || !(err.status === 400 || err.status === 403)) return false;
  return /No create access|1500028/i.test(String(err.detail || ""));
}
