<template>
  <DwDialog
    :model-value="modelValue"
    title="Projects Monitoring"
    subtitle="Find the projects that use a given sub-object and open them as a dashboard."
    icon="mdi-star-circle-outline"
    :busy="loading"
    max-width="480"
    @update:model-value="$emit('update:modelValue', $event)"
  >
    <form id="dw-default-form" class="dd-form" novalidate @submit.prevent="go">
      <div class="dw-field">
        <label class="dw-label" for="dd-sub">Sub-object type <span class="dw-required">*</span></label>
        <v-select id="dd-sub" v-model="subType" :items="subTypes" hide-details :disabled="loading" />
      </div>
      <div class="dw-field">
        <label class="dw-label" for="dd-name">Name <span class="dw-required">*</span></label>
        <v-text-field id="dd-name" v-model="name" placeholder="e.g. Field Testing" hide-details="auto" :disabled="loading" :error-messages="touched && !name.trim() ? 'Enter a name to search for.' : ''" @blur="touched = true" />
      </div>
      <div class="dw-field">
        <label class="dw-label" for="dd-status">Status <span class="dw-hint">(optional)</span></label>
        <v-combobox id="dd-status" v-model="status" :items="statuses" clearable hide-no-data hide-details :disabled="loading" />
      </div>
    </form>
    <template #footer>
      <button type="button" class="btn-outline" :disabled="loading" @click="$emit('update:modelValue', false)">Cancel</button>
      <button type="submit" form="dw-default-form" class="btn-primary" :class="{ 'btn-busy': loading }" :disabled="loading || !name.trim()">
        <span v-if="loading" class="dw-spinner" aria-hidden="true" />
        {{ loading ? "Searching…" : "Show Dashboard" }}
      </button>
    </template>
  </DwDialog>
</template>

<script>
import DwDialog from "@/components/common/DwDialog.vue";

export default {
  name: "DefaultDashboardDialog",
  components: { DwDialog },
  props: { modelValue: Boolean, loading: Boolean },
  emits: ["update:modelValue", "submit"],
  data: () => ({
    subType: "Task",
    name: "",
    status: "",
    touched: false,
    subTypes: ["Task", "Issue", "Phase", "Milestone", "Risk", "Route"],
    statuses: ["Active", "Create", "Assign", "Review", "Complete"],
  }),
  methods: {
    go() {
      this.touched = true;
      if (this.name.trim() && !this.loading)
        this.$emit("submit", { subType: this.subType, name: this.name, status: this.status || "" });
    },
  },
};
</script>

<style scoped>
.dd-form {
  display: flex;
  flex-direction: column;
  gap: var(--dw-sp-4);
}
</style>
