// Per-user sharing of dashboard documents (FR-11..FR-14).
//
// Sharing goes through a pluggable adapter so that views never call platform services
// directly. main.js registers services/pnoSharingAdapter.js (3DSpace ownership
// services used by the native "Share" command). Until an adapter is registered,
// isAvailable() is false and the UI hides the Share action.
// Every method returns only after the platform has confirmed the change.
//
// Adapter contract:
//   listGrantees(docId)                -> Promise<[{ id, name, login, level, inherited }]>
//   grant(docId, people, level)        -> Promise<void>   people from peopleApi.search
//   changeLevel(docId, grantee, level) -> Promise<void>
//   revoke(docId, grantee)             -> Promise<void>
//   listLevels(docId)    (optional)    -> Promise<[{ value, label }]>
//   canShare(docId)      (optional)    -> Promise<boolean>

import { ApiError, ERROR_CODES } from "./apiError";
import { SHARING } from "@/config/platformConfig";

let adapter = null;

export function registerSharingAdapter(impl) {
  const required = ["listGrantees", "grant", "changeLevel", "revoke"];
  if (!impl || required.some((m) => typeof impl[m] !== "function")) {
    throw new Error("Sharing adapter must implement " + required.join(", "));
  }
  adapter = impl;
}

const need = () => {
  if (!adapter) throw new ApiError(ERROR_CODES.NOT_CONFIGURED, { message: "Sharing isn't configured for this platform yet." });
  return adapter;
};

export default {
  isAvailable: () => !!adapter,
  listGrantees: async (docId) => need().listGrantees(docId),
  grant: async (docId, people, level) => need().grant(docId, people, level),
  changeLevel: async (docId, grantee, level) => need().changeLevel(docId, grantee, level),
  revoke: async (docId, grantee) => need().revoke(docId, grantee),
  listLevels: async (docId) => (need().listLevels ? adapter.listLevels(docId) : SHARING.levels),
  canShare: async (docId) => (!adapter ? false : adapter.canShare ? adapter.canShare(docId) : true),
};
