// Generic 3DSpace Document Web Services + File Collaboration Server (FCS) helpers.
// Used by dashboardDocumentApi.js; contains no dashboard-specific logic.
//
// Endpoints come from config/platformConfig.js. GET document by id is already used
// by this widget; create / modify / delete / check-in / download tickets follow the
// documented Document Web Services and must be confirmed for the target release
// (see docs/PLATFORM_INTEGRATION.md). FCS tickets are single-use and expire after
// 10 minutes, so a ticket is requested immediately before each transfer.

import http from "./httpClient.js";
import initApp from "@/utils/initApp.js";
import { PLATFORM } from "@/config/platformConfig";
import { ApiError, ERROR_CODES } from "./apiError";

const ctxHeaders = (ctx) => ({ SecurityContext: ctx || initApp.getCTX() });
const first = (json) => (Array.isArray(json?.data) ? json.data[0] : null);

// Normalises a document returned by the service into a flat object.
// "TRUE"/"FALSE" strings from the service; null when the field is absent.
const flag = (v) => (v === undefined || v === null || v === "" ? null : String(v).toUpperCase() === "TRUE");

export function toDocumentMeta(item) {
  if (!item) return null;
  const de = item.dataelements || item.attributes || {};
  const ownerInfo = item.relateddata?.ownerInfo?.[0]?.dataelements || null;
  const files = (item.relateddata?.files || []).map((f) => ({
    id: f.id,
    title: f.dataelements?.title || f.dataelements?.name || "",
    modified: f.dataelements?.modified || "",
  }));
  return {
    id: item.id,
    type: item.type || de.type || "",
    title: de.title || de.name || "",
    description: de.description || "",
    // The owner is returned in relateddata.ownerInfo (dataelements has no owner field).
    owner: ownerInfo?.name || de.owner || "",
    ownerName: [ownerInfo?.firstname, ownerInfo?.lastname].filter(Boolean).join(" ") || ownerInfo?.name || de.owner || "",
    ownerInfo,
    // Effective rights of the current user, as returned by 3DSpace.
    canModify: flag(de.hasModifyAccess),
    canDelete: flag(de.hasDeleteAccess),
    canDownload: flag(de.hasDownloadAccess),
    created: de.originated || de.created || "",
    modified: de.modified || "",
    state: de.state || "",
    files,
  };
}

function ticketOf(json) {
  const de = first(json)?.dataelements || {};
  if (!de.ticketURL) throw new ApiError(ERROR_CODES.SERVER, { message: "The file server didn't return a transfer ticket." });
  return de;
}

export default {
  async get(id, ctx) {
    const json = await http.get(`${PLATFORM.documents.base}/${encodeURIComponent(id)}`, { headers: ctxHeaders(ctx) });
    const doc = toDocumentMeta(first(json));
    if (!doc) throw new ApiError(ERROR_CODES.NOT_FOUND);
    return doc;
  },

  // Uploads content to FCS and returns the receipt to attach to a document.
  async uploadFile(content, fileName, ctx) {
    const ticket = ticketOf(await http.put(PLATFORM.documents.checkinTicket, undefined, { headers: ctxHeaders(ctx) }));
    const form = new FormData();
    form.append(ticket.ticketparamname || "__fcs__jobTicket", ticket.ticket);
    form.append("file_0", new Blob([content], { type: "application/json" }), fileName);
    const receipt = await http.post(ticket.ticketURL, undefined, { rawBody: form, responseType: "text" });
    if (!receipt || !String(receipt).trim()) {
      throw new ApiError(ERROR_CODES.SERVER, { message: "The file server didn't confirm the upload." });
    }
    return String(receipt).trim();
  },

  async downloadFile(docId, fileId, ctx) {
    const ticket = ticketOf(await http.put(PLATFORM.documents.downloadTicket(docId, fileId), undefined, { headers: ctxHeaders(ctx) }));
    return http.get(ticket.ticketURL, { responseType: "text" });
  },

  // Creates a document with one file in a single call (file uploaded first).
  async create({ title, description, type, policy, fileName, content }, ctx) {
    const receipt = await this.uploadFile(content, fileName, ctx);
    // Document Web Services read the object's fields from "dataelements" (the same block
    // used by modify and returned in responses). Fields sent elsewhere are ignored, which
    // leaves the document with an auto-generated name and an empty description.
    const body = {
      data: [
        {
          type,
          dataelements: { title, description, ...(policy && { policy }) },
          relateddata: { files: [{ dataelements: { title: fileName, receipt } }] },
        },
      ],
    };
    const json = await http.post(PLATFORM.documents.base, body, { headers: ctxHeaders(ctx) });
    const doc = toDocumentMeta(first(json));
    if (!doc?.id) throw new ApiError(ERROR_CODES.SERVER, { message: "The document was not created." });
    return doc;
  },

  // Updates title/description and, when content is given, checks in a new file version.
  async update(doc, { title, description, fileName, content }, ctx) {
    const item = { id: doc.id, dataelements: {} };
    if (title !== undefined) item.dataelements.title = title;
    if (description !== undefined) item.dataelements.description = description;
    if (content !== undefined) {
      const receipt = await this.uploadFile(content, fileName, ctx);
      const existing = doc.files.find((f) => f.title === fileName) || doc.files[0];
      item.relateddata = {
        files: [{ ...(existing && { id: existing.id }), dataelements: { title: fileName, receipt } }],
      };
    }
    const json = await http.put(`${PLATFORM.documents.base}/${encodeURIComponent(doc.id)}`, { data: [item] }, { headers: ctxHeaders(ctx) });
    return toDocumentMeta(first(json)) || doc;
  },

  remove(id, ctx) {
    return http.delete(`${PLATFORM.documents.base}/${encodeURIComponent(id)}`, { headers: ctxHeaders(ctx) });
  },
};
